import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { CommonModule } from '@angular/common';
import { RouterLink } from '@angular/router';
import { FileService } from 'src/app/core/services/file.service';

@Component({
  selector: 'app-student-classes',
  standalone: true,
  imports: [CommonModule, RouterLink],
  templateUrl: './student-classes.component.html',
  styleUrls: ['./student-classes.component.scss']
})
export class StudentClassesComponent implements OnInit {
  slug!: string;
  classes: any[] = [];
  loading = true;

  constructor(private route: ActivatedRoute, private fileService: FileService) {}

  ngOnInit() {
    this.slug = this.route.snapshot.params['slug'];
    this.loadClasses();
  }

  loadClasses() {
    this.fileService.getFilesByProf(this.slug).subscribe({
      next: (files: any[]) => {
        const classesMap = new Map();
        files.forEach(f => {
          if (f.classroomName && !classesMap.has(f.classroomName)) {
            classesMap.set(f.classroomName, { id: f.classroomId, name: f.classroomName, description: f.classroomDescription });
          }
        });
        this.classes = Array.from(classesMap.values());
        this.loading = false;
      },
      error: err => {
        console.error('Erreur chargement classes:', err);
        this.loading = false;
      }
    });
  }
}
<section class="container py-5">
  <h2 class="fw-bold mb-4 text-center">Classes du professeur</h2>

  <div *ngIf="loading" class="text-center my-5">
    <div class="spinner-border text-primary"></div>
  </div>

  <div *ngIf="!loading && classes.length > 0" class="row g-4">
    <div class="col-md-4" *ngFor="let c of classes">
      <div class="card shadow-sm text-center p-3">
        <h4 class="fw-bold">{{ c.name }}</h4>
        <p class="text-muted">{{ c.description }}</p>
        <a [routerLink]="['/student/join']" [queryParams]="{ code: c.accessCode, id: c.id }" class="btn btn-primary">
          Accéder à la classe
        </a>
      </div>
    </div>
  </div>

  <div *ngIf="!loading && !classes.length" class="alert alert-info text-center">
    Aucune classe pour ce professeur.
  </div>
</section>
